<style>
body{font:13px/1.45 system-ui,sans-serif;margin:0;padding:24px;color:#111;max-width:860px}
h1{font-size:18px;margin:0}.m{color:#555;font-size:11px}.head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2px solid #111;padding-bottom:8px}
.doc{text-align:right}.doc h2{margin:0;font-size:22px;letter-spacing:.03em}.kv{display:grid;grid-template-columns:repeat(4,1fr);gap:6px 16px;margin:12px 0}
.kv div span,.lbl{display:block;font-size:10px;text-transform:uppercase;color:#666;letter-spacing:.04em}
table{width:100%;border-collapse:collapse;margin-top:6px}td,th{padding:5px 6px;border-bottom:1px solid #ccc;text-align:left;vertical-align:top}th{font-size:11px;color:#444;background:#f3f4f6}.r{text-align:right}
tfoot td{font-weight:700;border-top:2px solid #111}.sig{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:48px}.sig div{border-top:1px solid #111;padding-top:4px;font-size:11px}
.stamp{display:inline-block;border:2px solid #111;border-radius:6px;padding:2px 8px;font-weight:700;font-size:11px;margin-top:4px}
.fn{border:1.5px solid #111;border-radius:6px;margin:14px 0;page-break-inside:avoid}.fn h3{margin:0;padding:6px 10px;background:#111;color:#fff;font-size:14px;display:flex;justify-content:space-between}
.fn .body{padding:8px 10px}.dept{display:grid;grid-template-columns:repeat(2,1fr);gap:8px 18px;margin-top:6px}.dept div{border-top:1px solid #ddd;padding-top:4px}
.pre{white-space:pre-line}.big{font-size:20px;font-weight:700}.muted{color:#666}.note{font-size:11px;color:#444}
@media print{button,.noprint{display:none}body{padding:0}}
</style>
